import{_ as p,o,c as t,a2 as n}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Input-Selection-Options.md","filePath":"manual-zh/Input-Selection-Options.md","lastUpdated":1785684581000}'),a={name:"manual-zh/Input-Selection-Options.md"};function s(c,e,d,r,l,i){return o(),t("div",null,[...e[0]||(e[0]=[n('<h3 id="_19-6-输入选择选项" tabindex="-1">19.6 输入选择选项 <a class="header-anchor" href="#_19-6-输入选择选项" aria-label="Permalink to &quot;19.6 输入选择选项&quot;">​</a></h3><p><code>dir</code> 和 <code>convert</code> 命令默认对源 SPV 文件中的所有对象进行操作，输出查看器窗口中不可见的对象除外。用户可以指定这些选项以选择输入对象的子集。当使用多个选项时，仅选择满足所有选项的对象：</p><p>--select=[^]class…</p><p>仅包含给定类别的对象；带有前导 ‘^’ 时，仅包含不在该类别中的对象。使用逗号分隔多个类别。支持的类别有：</p><blockquote><p><code>charts headings logs models tables texts trees warnings outlineheaders pagetitle notes unknown other</code></p></blockquote><p>使用 --select=help 打印此类别列表。</p><p>--commands=[^]command… --subtypes=[^]subtype… --labels=[^]label…</p><p>仅包含具有指定命令、子类型或标签的对象。带有前导 ‘^’ 时，仅包含不匹配的对象。可以指定多个值，以逗号分隔。值末尾的星号充当通配符。</p><p>--command 选项匹配命令标识符，不区分大小写。由单个命令产生的所有对象使用相同、唯一的命令标识符。命令标识符始终为英文，不受输出语言影响。它们通常与 PSPP 语法中的命令名不同。使用 <code>pspp-output</code> 程序的 <code>dir</code> 命令可在特定输出中打印命令标识符。</p><p>--subtypes 选项匹配命令中的特定表格，不区分大小写。子类型不一定唯一：产生类似输出表格的两个命令可能使用相同的子类型。子类型始终为英文，<code>dir</code> 会打印它们。</p><p>--labels 选项匹配表格输出中的标签（即表格标题）。标签受输出语言、变量名和标签、拆分文件设置及其他因素影响。</p><p>--nth-commands=n…</p><p>仅包含来自与 --command 匹配的第 n 个命令的对象（如果未指定 --command，则为第 n 个命令整体），其中 n 为 1 表示第一个命令，2 表示第二个，依此类推。</p><p>--instances=instance…</p><p>包含在使用其他条件在单个命令中匹配的对象的指定实例。实例可以是数字（1 表示第一个实例，2 表示第二个，依此类推）或 <code>last</code> 表示最后一个实例。</p><p>--show-hidden</p><p>在输出中包含隐藏的输出对象。默认情况下它们被排除。</p><p>--or</p><p>分隔两组选择选项。任一组选项选择的对象都包含在输出中。</p><p>以下额外的输入选择选项主要供 PSPP 开发人员使用：</p><p>--errors</p><p>仅包含读取时导致错误的对象。配合 <code>convert</code> 命令使用时，这与 --force 选项结合最有用。</p><p>--members=member…</p><p>仅包含包含所列 Zip 文件成员的对象。可以包含多个名称，以逗号分隔。SPV 文件中的成员可通过在 <code>dir</code> 命令中添加 --show-members 选项列出，或使用许多操作系统附带的 <code>zipinfo</code> 程序列出。<code>pspp-output</code> 读取 SPV 文件时打印的错误消息通常也包含成员名称。</p><p>--member-names</p><p>显示与每个对象自身正上方关联的 Zip 成员的名称。</p>',26)])])}const _=p(a,[["render",s]]);export{u as __pageData,_ as default};
